import{_ as i,I as a,c as d,o as Q,ak as p,J as t}from"./chunks/framework.ZgTfbhW9.js";const h=JSON.parse('{"title":"LiteLoaderQQNT 兼容","description":"","frontmatter":{},"headers":[],"relativePath":"framework/adapt-liteloaderqqnt.md","filePath":"framework/adapt-liteloaderqqnt.md"}'),n={name:"framework/adapt-liteloaderqqnt.md"};function l(s,e,L,N,T,c){const r=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return Q(),d("div",null,[e[0]||(e[0]=p('<h1 id="liteloaderqqnt-兼容" tabindex="-1">LiteLoaderQQNT 兼容 <a class="header-anchor" href="#liteloaderqqnt-兼容" aria-label="Permalink to “LiteLoaderQQNT 兼容”">​</a></h1><p>QwQNT 框架拥有与 LiteLoaderQQNT 框架生态兼容的能力。</p><p>QwQNT 框架拥有多种兼容 LiteLoaderQQNT 框架生态的方法，请任选其一使用。</p><h2 id="框架嵌套法" tabindex="-1">框架嵌套法 <a class="header-anchor" href="#框架嵌套法" aria-label="Permalink to “框架嵌套法”">​</a></h2><p>LiteLoaderQQNT 框架可以原生作为 QwQNT 框架的插件加载。</p><p>这需要 LiteLoaderQQNT 框架 1.3.0 及以上版本。</p><p>使用该方法无需执行 LiteLoaderQQNT 框架的安装步骤，只需将其放置在 QwQNT 框架的插件文件夹下即可。</p><p>安装 LiteLoaderQQNT 框架的插件仍需按照 LiteLoaderQQNT 框架的插件安装方法完成。</p><h2 id="插件兼容法" tabindex="-1">插件兼容法 <a class="header-anchor" href="#插件兼容法" aria-label="Permalink to “插件兼容法”">​</a></h2><p>通过 QwQNT-LiteLoaderQQNTAdapter 插件，可以让部分 LiteLoaderQQNT 框架插件直接运行在 QwQNT 框架下。</p><p>你需要保证 QwQNT-LiteLoaderQQNTAdapter 插件的前置插件均已安装并启用。</p><p>该方法不保证所有 LiteLoaderQQNT 插件均能正常运行。</p><p>QwQNT-LiteLoaderQQNTAdapter 插件仅可于用户群组中获得。</p><h2 id="移植法" tabindex="-1">移植法 <a class="header-anchor" href="#移植法" aria-label="Permalink to “移植法”">​</a></h2><p>你可以选择使用 LiteLoaderQQNT 插件的 QwQNT 移植版或适配版。</p><p>这些移植插件可能由 QwQNT 框架管理组成员、原 LiteLoaderQQNT 插件开发者或热心用户编写。</p><p>对于前两者编写的插件，安全性均可得到保障。对于热心用户编写的移植版插件，请谨慎使用。</p><p>或者你也可以自己进行移植。</p>',18)),t(r),t(o)])}const m=i(n,[["render",l]]);export{h as __pageData,m as default};
